"""决战状态机的阶段处理器（v6）。

核心流程：

- ENTER_MAP：检测小关 → 副官切换 → 小关快照 → 进图；
- CHOOSE_FLEET：按优先级买船 → 黄色确定 → 回地图；
- PREPARE_COMBAT：紫貂/奇尔沙治技能 → 编队/修理/出征；
- IN_COMBAT：战斗引擎（跳过结算采集）→ 连点回地图；
- RETREAT：确认撤退 → 恢复小关快照。

所有等待都是条件轮询，不在决战流程里写死 ``time.sleep``。
"""

from __future__ import annotations

import time
from typing import TYPE_CHECKING

from autowsgr.combat.engine import run_combat
from autowsgr.combat.plan import CombatMode, CombatPlan, NodeDecision
from autowsgr.infra import ActionFailedError, ChapterResetError
from autowsgr.infra.logger import get_logger
from autowsgr.ops.decisive.base import DecisiveBase
from autowsgr.ops.decisive.logic import DecisiveLogic, SortieMode
from autowsgr.types import (
    ConditionFlag,
    DecisiveEntryStatus,
    DecisivePhase,
    ShipDamageState,
)
from autowsgr.ui.decisive import ChapterResetOutcome, SortieOutcome
from autowsgr.ui.utils import wait_for_stable_screen


if TYPE_CHECKING:
    from autowsgr.types import FleetSelection


_log = get_logger('ops.decisive')


class DecisivePhaseHandlers(DecisiveBase):
    """决战阶段处理器子类。"""

    # ── 状态同步 ──────────────────────────────────────────────────────────

    def _scan_fleet_with_retry(
        self,
        *,
        attempts: int = 3,
    ) -> tuple[int, dict[str, FleetSelection]]:
        """扫描购买页；界面关闭后不再尝试回到该界面。"""
        screen = self._map.wait_for_fleet_overlay_stable()
        score = self._state.score
        selections: dict[str, FleetSelection] = {}

        for attempt in range(1, attempts + 1):
            status: list[bool] = []
            score, selections = self._map.recognize_fleet_options(
                screen,
                fallback_score=0,
                score_status=status,
            )
            score_ok = not status or status[-1]
            if selections and score_ok:
                return score, selections
            if not self._map.is_fleet_overlay_open():
                return score, {}
            if attempt < attempts and (not score_ok or not selections):
                _log.warning(
                    '[决战] 战备舰队 OCR 失败 (点数识别={}, 选项={})，第 {} 次重试',
                    score_ok,
                    bool(selections),
                    attempt,
                )
                screen = self._map.wait_for_fleet_overlay_stable(timeout=2.0)
        return score, selections

    def _route_after_overlay(self) -> None:
        """购买/前进点 overlay 关闭后，重新探测下一状态。"""
        phase = self._map.detect_decisive_phase()
        if phase is None:
            phase = DecisivePhase.PREPARE_COMBAT
        _log.info('[决战] overlay 后状态: {}', phase.name)
        self._state.phase = phase

    # ── 进入 / 等待 ──────────────────────────────────────────────────────

    def _handle_enter_map(self) -> None:
        """检测入口状态 → 副官切换 → 小关快照 → 进入地图。"""
        entry_status = self._battle_page.detect_entry_status()
        did_reset = False

        if entry_status == DecisiveEntryStatus.REFRESH:
            if self._state.stage_enter_snapshot is not None:
                # 撤退后回到总览：快照已恢复，绝不能因为入口显示「重置关卡」
                # 就再消耗一张磁盘重置整章。直接尝试进入本关。
                _log.warning(
                    '[决战] 撤退后入口仍为「可重置」，跳过章节重置（快照 stage={}）',
                    self._state.stage_enter_snapshot.stage,
                )
            else:
                _log.info('[决战] 检测到「重置关卡」状态，执行章节重置')
                outcome = self._battle_page.reset_chapter()
                # 三态结果：只有船坞满进 DOCK_FULL；其它失败带截图抛错，
                # 不能一律当成 DOCK_FULL（磁盘不足/网络重试/弹窗变体）。
                if outcome is ChapterResetOutcome.DOCK_FULL:
                    _log.warning('[决战] 章节重置被「船坞已满」拦截 → DOCK_FULL')
                    self._state.phase = DecisivePhase.DOCK_FULL
                    return
                if outcome is not ChapterResetOutcome.RESET:
                    raise ChapterResetError(
                        f'决战 Ex-{self._config.chapter}: 重置后入口状态未变为'
                        '「已重置」（磁盘不足 / 网络重试 / 弹窗变体 / 点击未生效）',
                        screen=self._ctrl.screenshot(),
                    )
                did_reset = True
                # reset_chapter 已轮询验证入口=REFRESHED，无需重复探测。
                entry_status = DecisiveEntryStatus.REFRESHED

        if entry_status == DecisiveEntryStatus.CANT_FIGHT:
            raise RuntimeError(
                f'决战 Ex-{self._config.chapter}: 入口状态为「无法出击」，其他关卡正在进行中'
            )

        if not self._entry_checked:
            self._resume_mode = (
                not did_reset
                and entry_status in (DecisiveEntryStatus.REFRESHED, DecisiveEntryStatus.CHALLENGING)
            )
            self._entry_checked = True
        else:
            # 撤退 / 下一小关：快照或已知舰船已足够，不再扫描编队覆盖状态。
            self._resume_mode = False

        _log.info('[决战] 入口状态: {}', entry_status.value)
        self._state.stage = self._battle_page.detect_stage(
            self._ctrl.screenshot(),
            self._config.chapter,
        )

        target_instructor = self._logic.instructor_for_stage(self._state.stage)
        if target_instructor:
            self._battle_page.ensure_instructor(target_instructor)
            self._state.instructor = target_instructor

        snapshot = self._state.stage_enter_snapshot
        if snapshot is None or snapshot.stage != self._state.stage:
            self._state.capture_stage_snapshot()
            _log.info(
                '[决战] 小关快照: stage={}, score={}, ships={}, instructor={} Lv.{}',
                self._state.stage,
                self._state.score,
                self._state.ship_levels,
                self._state.instructor,
                self._state.instructor_level,
            )

        self._battle_page.click_enter_map()
        self._use_last_fleet_attempts = 0
        self._wait_deadline = time.monotonic() + 15.0
        self._state.phase = DecisivePhase.WAITING_FOR_MAP

    def _handle_waiting_for_map(self) -> None:
        """等待地图页加载：单次截图检测 → 转到对应阶段或继续等待。"""
        screen = self._ctrl.screenshot()
        phase = self._map.detect_decisive_phase(screen)
        if phase is not None:
            self._state.phase = phase
            return

        if time.monotonic() >= self._wait_deadline:
            raise TimeoutError('等待地图页或 overlay 超时')
        if self._ctx.stop_event.wait(0.05):
            from autowsgr.infra import TaskStopRequested

            raise TaskStopRequested('决战等待地图')

    def _handle_use_last_fleet(self) -> None:
        """点击「使用上次舰队」+ 确定；连续 3 次仍失败则明确报错。"""
        self._use_last_fleet_attempts += 1
        attempt = self._use_last_fleet_attempts
        _log.info('[决战] 「使用上次舰队」第 {} 次尝试', attempt)

        if self._map.use_last_fleet(timeout=8.0):
            self._wait_deadline = time.monotonic() + 10.0
            self._state.phase = DecisivePhase.WAITING_FOR_MAP
            return

        _log.warning(
            '[决战] 「使用上次舰队」第 {}/3 次失败：点击后仍停留在选船页',
            attempt,
        )
        if attempt >= 3:
            raise ActionFailedError(
                '决战-使用上次舰队',
                f'连续 {attempt} 次点击「使用上次舰队 + 确定」后仍停留在选船页',
            )

        # 不直接锁死 USE_LAST_FLEET：交给 WAITING_FOR_MAP 重新识别，
        # 若失败其实是因为页面已切到地图，也能正常继续。
        self._wait_deadline = time.monotonic() + 10.0
        self._state.phase = DecisivePhase.WAITING_FOR_MAP

    def _handle_dock_full(self) -> None:
        """船坞已满: 自动解装 → ENTER_MAP。"""
        _log.warning('[决战] 处理船坞已满')
        self._do_dock_full_destroy()  # type: ignore[attr-defined]  # from DecisiveChapterOps
        self._prepare_entry_state()  # type: ignore[attr-defined]  # from DecisiveChapterOps
        self._state.phase = DecisivePhase.ENTER_MAP

    # ── 购买舰队 ──────────────────────────────────────────────────────────

    def _handle_choose_fleet(self) -> None:
        """战备舰队获取：OCR 5 张卡 → 优先级选卡 → 黄色确定。"""
        self._has_chosen_fleet = True
        _log.info('[决战] 战备舰队获取')

        score, selections = self._scan_fleet_with_retry()
        self._state.score = score if score is not None else self._state.score

        # 目标舰队（6 潜艇 + U-47/U-1206）已齐且副官未满级：
        # 停止买船，关闭购买页，把点数全部用于买经验。
        if (
            self._logic.target_fleet_complete()
            and self._state.instructor_level < self._config.instructor_max_level
        ):
            self._close_purchase_and_route(
                '目标舰队已齐，停止买船转买经验',
                allow_retreat=False,
            )
            self._buy_experience_with_remaining()
            self._maybe_use_instructor_skill()
            self._maybe_use_kearsarge_skill()
            return

        # 1) 一张船都买不起：先刷新；刷新后仍买不起就关闭购买页继续。
        if (
            not self._logic.has_affordable_ship(selections)
            and not self._logic.opening_ready()
        ):
            if self._logic.refresh_allowed():
                score, selections = self._refresh_fleet_and_rescan('无任何可负担船只')
            if not self._logic.has_affordable_ship(selections):
                self._close_purchase_and_route('刷新后仍无任何可负担船只')
                self._after_purchase_page_closed()
                return

        targets = self._logic.choose_purchases(selections)
        need_refresh = (
            not self._logic.opening_offer_complete(selections)
            if self._logic.is_opening_purchase_point()
            else not targets
        )
        if need_refresh and self._logic.refresh_allowed():
            score, selections = self._refresh_fleet_and_rescan('未凑齐开局/无目标')
            targets = self._logic.choose_purchases(selections)

        if not targets:
            self._close_purchase_and_route('购买页无目标')
            self._after_purchase_page_closed()
            return

        _log.info('[决战] 选择购买: {} (余额 {})', targets, self._state.score)
        bought = self._map.buy_fleet_offers(targets, selections)
        if not bought and self._logic.refresh_allowed():
            # OCR 可能把 4 看成 3；刷新一次后重试。仍失败则关闭，不撤退。
            score, selections = self._refresh_fleet_and_rescan('购买确认失败')
            targets = self._logic.choose_purchases(selections)
            if targets:
                _log.info('[决战] 刷新后重试购买: {}', targets)
                bought = self._map.buy_fleet_offers(targets, selections)

        if not bought:
            self._close_purchase_and_route('购买确认失败')
            self._after_purchase_page_closed()
            return

        spent = sum(selections[name].cost for name in bought)
        for name in bought:
            self._state.add_ship(name)
        self._state.score = max(0, self._state.score - spent)
        _log.info(
            '[决战] 购买完成，现有舰船: {}，余额: {}',
            self._state.ship_levels,
            self._state.score,
        )
        # 每买完一艘船，剩余点数立即转成副官经验；满 10 级后自然跳过。
        self._buy_experience_with_remaining()
        # 购买页已经关闭，此时才是释放副官技能的时机（所有节点）。
        self._maybe_use_instructor_skill()
        self._maybe_use_kearsarge_skill()
        self._route_after_overlay()

    def _refresh_fleet_and_rescan(
        self,
        reason: str,
    ) -> tuple[int | None, dict[str, FleetSelection]]:
        """刷新购买页并重新 OCR。"""
        self._state.refresh_count += 1
        _log.info(
            '[决战] {}，刷新购买页 ({}/{})',
            reason,
            self._state.refresh_count,
            self._config.max_refresh_per_node,
        )
        self._map.refresh_fleet()
        score, selections = self._scan_fleet_with_retry()
        self._state.score = score if score is not None else self._state.score
        return score, selections

    def _close_purchase_and_route(self, reason: str, *, allow_retreat: bool = True) -> None:
        """无可购买目标/买不起时关闭购买页。

        普通节点关闭后继续；E6-2 A 关闭后按配置撤退重刷。
        目标舰队已齐、需要转买经验时用 ``allow_retreat=False``，
        避免在 6-2 A 把点数浪费在撤退上。
        """
        _log.info('[决战] {}，关闭购买页', reason)
        if not self._map.close_fleet_overlay():
            raise ActionFailedError(f'{reason}，关闭购买页失败')
        if allow_retreat and self._logic.should_retreat_after_purchase_close():
            _log.info('[决战] E6-2 A 购买页关闭后撤退重刷')
            self._state.phase = DecisivePhase.RETREAT
            return
        self._route_after_overlay()

    def _handle_advance_choice(self) -> None:
        """选择前进点：路线固定走第一个。"""
        _log.info('[决战] 选择前进点')
        self._map.select_advance_card(self._logic.advance_card_index())
        self._route_after_overlay()

    # ── 战斗准备 ──────────────────────────────────────────────────────────

    def _handle_prepare_combat(self) -> None:
        """技能 → 编队/修理 → 出征。"""
        # C 点等节点的战备舰队弹窗可能在战斗结算后延迟出现；先等画面
        # 稳定再判定 overlay，避免把购买页误判为地图页后去点“编队”。
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.0,
            interval=0.15,
            stable_frames=2,
            source='决战出征准备前',
            stop_event=self._ctx.stop_event,
        )
        screen = self._ctrl.screenshot()
        overlay_phase = self._map.detect_decisive_phase(screen)
        if overlay_phase in (
            DecisivePhase.CHOOSE_FLEET,
            DecisivePhase.ADVANCE_CHOICE,
            DecisivePhase.USE_LAST_FLEET,
        ):
            _log.info('[决战] 出征准备前检测到 overlay，切回阶段: {}', overlay_phase.name)
            self._state.phase = overlay_phase
            return

        if self._state.node == 'U':
            recognized_node = self._map.recognize_node()
            if recognized_node == 'CHOOSE_FLEET':
                self._state.phase = DecisivePhase.CHOOSE_FLEET
                return
            self._state.node = recognized_node
            self._state.refresh_count = 0

        _log.info('[决战] 出征准备 (小关 {} 节点 {})', self._state.stage, self._state.node)

        # 恢复模式：只扫描编队/舰船，不读血量。
        if self._resume_mode:
            _log.info('[决战] 恢复模式: 扫描当前编队')
            fleet = self._map.check_fleet()
            names = [name for name in fleet if name]
            if names:
                self._state.ship_levels = {
                    name: max(1, self._state.ship_levels.get(name, 1)) for name in names
                }
                self._state.fleet = ['', *[name or '' for name in fleet]]
                while len(self._state.fleet) < 7:
                    self._state.fleet.append('')
            else:
                # 空编队说明本局还没上阵（例如刚买完船），绝不能把刚买的
                # ship_levels 清空，也不能用购买后的状态覆盖小关快照。
                _log.info('[决战] 恢复模式未发现现有编队，保留本局购买状态')
            self._resume_mode = False

        # 6-1 / 6-2：紫貂；6-3：奇尔沙治（仅 J 点特殊流程）。
        if self._logic.instructor_for_stage() == self._state.instructor:
            level = self._map.read_skill_level()
            if level is not None:
                self._state.instructor_level = level
        # 全局规则：先处理战备舰队购买页，购买页关闭后才释放技能。
        # 这里不再点技能，避免购买页打开时点击无效却记录“已用”。

        fleet = self._logic.get_best_fleet()
        if self._logic.must_retreat(fleet):
            _log.info('[决战] 舰船不足, 准备撤退: {}', fleet)
            self._state.phase = DecisivePhase.RETREAT
            return

        plan = self._logic.sortie_plan(fleet, current_fleet=self._state.fleet)
        self._state.fleet = fleet
        _log.info('[决战] 出征方案: {} ({})', plan.mode.value, plan.reason)

        if plan.mode is SortieMode.MANUAL:
            # 手动编队默认不主动修理；只有 E6-3 J 例外，始终先修再出征。
            self._manual_repair_and_sortie(
                fleet,
                always_repair=self._logic.should_use_kearsarge_skill(),
            )
            return

        outcome = self._map.click_sortie_and_probe()
        _log.info('[决战] 点出征结果: {}', outcome.value)
        if outcome is SortieOutcome.BATTLE:
            self._state.phase = DecisivePhase.IN_COMBAT
            return
        if outcome is SortieOutcome.DAMAGE_CONFIRM:
            self._map.cancel_damage_confirm()
        # 只有确实看到大破确认框/旗舰短条才先修理；
        # STILL_MAP（没看到任何弹窗）按“点击未生效”处理，修理交给准备页的弹窗探测。
        self._manual_repair_and_sortie(
            fleet,
            always_repair=outcome is not SortieOutcome.STILL_MAP,
        )

    def _after_purchase_page_closed(self) -> None:
        """购买页关闭后（即使没买船）再考虑释放技能；撤退前不浪费。"""
        if self._state.phase is not DecisivePhase.RETREAT:
            self._maybe_use_instructor_skill()
            self._maybe_use_kearsarge_skill()

    def _maybe_use_instructor_skill(self) -> None:
        """达到 3/8 级且未用则释放技能。"""
        if self._logic.next_skill_threshold() is not None:
            self._apply_instructor_skill()

    def _maybe_use_kearsarge_skill(self) -> None:
        """购买页关闭后，在 6-3 J 释放奇尔沙治技能。"""
        if self._kearsarge_skill_used:
            return
        if self._logic.should_use_kearsarge_skill():
            self._apply_kearsarge_skill()

    def _apply_instructor_skill(self) -> None:
        """紫貂：OCR 等级 → 点技能 → 连点买经验（严格顺序）。"""
        threshold = self._logic.next_skill_threshold()
        if threshold is None:
            return
        if not self._state.instructor:
            self._state.instructor = self._logic.instructor_for_stage()

        _log.info(
            '[决战] 使用技能: instructor={}, level={}, threshold={}',
            self._state.instructor,
            self._state.instructor_level,
            threshold,
        )
        self._map.click_skill()
        self._run_buy_exp_loop()
        self._state.skill_used_levels.add(threshold)

    def _buy_experience_with_remaining(self) -> None:
        """买船后用剩余点数买经验；满 10 级后不再买。"""
        if self._state.instructor_level >= self._config.instructor_max_level:
            return
        self._run_buy_exp_loop()

    def _run_buy_exp_loop(self) -> None:
        """读取当前点数/等级并连续购买经验值。"""
        current_score = self._map.read_score(map_page=True)
        if current_score is not None:
            self._state.score = current_score
        current_level = self._map.read_skill_level()
        if current_level is not None:
            self._state.instructor_level = current_level
        if (
            self._state.instructor_level >= self._config.instructor_max_level
            or self._state.score < self._config.buy_exp_cost
        ):
            return

        outcome = DecisiveLogic.run_buy_exp_loop(
            initial_score=self._state.score,
            initial_level=self._state.instructor_level,
            cost=self._config.buy_exp_cost,
            max_level=self._config.instructor_max_level,
            max_clicks=self._config.buy_exp_max_clicks,
            read_score=lambda: self._map.read_score(map_page=True),
            read_level=lambda: self._map.read_skill_level(),
            is_disabled=lambda: self._map.is_buy_exp_disabled(),
            click_buy=lambda: self._map.click_buy_exp(),
            handle_popup=lambda: self._map.drain_insufficient_popup(),
        )
        self._state.score = outcome.score
        self._state.instructor_level = outcome.level
        _log.info(
            '[决战] 买经验结束: clicks={}, score={}, level={}, reason={}',
            outcome.clicks,
            outcome.score,
            outcome.level,
            outcome.stop_reason.value,
        )

    def _apply_kearsarge_skill(self) -> None:
        """奇尔沙治：J 点前点一次技能，效果持续到进入战斗。"""
        if not self._state.instructor:
            self._state.instructor = self._logic.instructor_for_stage()
        _log.info('[决战] 使用奇尔沙治技能（J 点前）')
        self._map.click_skill()
        self._kearsarge_skill_used = True

    def _manual_repair_and_sortie(
        self,
        fleet: list[str],
        *,
        always_repair: bool = False,
    ) -> None:
        """编队 → 开始出征；只有大破弹窗/旗舰短条才修理。

        E6-3 J（``always_repair=True``）是唯一例外：没有弹窗也先全部修理。
        """
        page = self._map.enter_formation()
        if page is None:
            _log.info('[决战] 编队前出现新 overlay，切回状态机处理')
            self._route_after_overlay()
            return
        page.ensure_fleet(fleet)
        if always_repair:
            _log.info('[决战] E6-3 J / 已确认大破，先全部修理')
            page.apply_full_repair()
        else:
            _log.info('[决战] 手动编队：先直接开始出征，出现大破弹窗再修理')

        # 最多 3 次“开始出征”：只有 DAMAGE_CONFIRM / FLAGSHIP_SEVERE 才修理；
        # STILL_MAP 视为点击/转场未生效，重试但不修理。
        for attempt in range(1, 4):
            page.start_battle()
            # 手动出征给 5s 的转场窗口；出现大破弹窗/短条会立即返回。
            outcome = self._map.wait_for_start_outcome(timeout=5.0)
            _log.info('[决战] 开始出征结果(第 {} 次): {}', attempt, outcome.value)
            if outcome is SortieOutcome.BATTLE:
                self._state.phase = DecisivePhase.IN_COMBAT
                return
            if outcome is SortieOutcome.DAMAGE_CONFIRM:
                self._map.cancel_damage_confirm()
                page.apply_full_repair()
                continue
            if outcome is SortieOutcome.FLAGSHIP_SEVERE:
                page.apply_full_repair()
                continue
            _log.warning('[决战] 未检测到大破提示，重试开始出征（不修理）')

        raise ActionFailedError('决战开始出征后仍未进入战斗')

    # ── 战斗 ──────────────────────────────────────────────────────────────

    def _handle_combat(self) -> None:
        """战斗阶段：委托 CombatEngine，并跳过结算页处理器。"""
        _log.info('[决战] 开始战斗 (小关 {} 节点 {})', self._state.stage, self._state.node)
        plan = CombatPlan(
            name=f'决战-{self._state.stage}-{self._state.node}',
            mode=CombatMode.DECISIVE,
            default_node=NodeDecision(
                formation=self._logic.get_formation(),
                night=self._logic.should_pursue_night(),
            ),
            skip_result_handler=True,
        )
        result = run_combat(
            self._ctx,
            plan,
            ship_stats=[ShipDamageState.NORMAL] * 6,
        )
        _log.info('[决战] 战斗结束: {} (节点 {})', result.flag.value, self._state.node)
        if result.flag == ConditionFlag.DOCK_FULL:
            _log.warning('[决战] 战斗中检测到船坞已满，转到 DOCK_FULL')
            self._state.phase = DecisivePhase.DOCK_FULL
        else:
            self._state.phase = DecisivePhase.NODE_RESULT

    # ── 节点结果 & 通关 ──────────────────────────────────────────────────

    def _handle_node_result(self) -> None:
        """节点战斗结束：连点回地图，推进节点或进入小关结算。"""
        if self._logic.is_stage_end():
            _log.info('[决战] 小关 {} 终止节点 {} 已到达', self._state.stage, self._state.node)
            self._map.finish_stage_clear()
            self._state.phase = DecisivePhase.STAGE_CLEAR
            return

        phase = self._map.finish_battle_to_map()
        if phase == DecisivePhase.DOCK_FULL:
            self._state.phase = DecisivePhase.DOCK_FULL
            return

        previous = self._state.node
        self._state.node = self._logic.next_node()
        self._state.refresh_count = 0
        _log.info('[决战] 节点递进: {} -> {}', previous, self._state.node)

        if phase in (DecisivePhase.CHOOSE_FLEET, DecisivePhase.ADVANCE_CHOICE):
            self._state.phase = phase
        else:
            self._state.phase = DecisivePhase.PREPARE_COMBAT

    def _handle_stage_clear(self) -> None:
        """小关通关：快速跳过结算 → 下一小关或大关。"""
        stage = self._state.stage
        _log.info('[决战] 小关 {} 通关!', stage)
        self._map.finish_stage_clear()
        self._state.begin_new_stage()
        self._resume_mode = False
        if stage >= 3:
            self._state.phase = DecisivePhase.CHAPTER_CLEAR
        else:
            self._state.phase = DecisivePhase.ENTER_MAP

    # ── 撤退与暂离 ──────────────────────────────────────────────────────

    def _execute_retreat(self) -> None:
        """执行撤退，并恢复进入本小关时的快照。"""
        _log.info('[决战] 执行撤退')
        self._map.open_retreat_dialog()
        self._map.confirm_retreat()
        self._resume_mode = False
        if self._state.restore_stage_snapshot():
            _log.info(
                '[决战] 快照恢复: stage={}, score={}, ships={}, instructor={} Lv.{}',
                self._state.stage,
                self._state.score,
                self._state.ship_levels,
                self._state.instructor,
                self._state.instructor_level,
            )
        else:
            _log.warning('[决战] 无小关快照，撤退后执行全量重置')
            self._state.reset()

    def _execute_leave(self) -> None:
        """执行暂离操作。"""
        _log.info('[决战] 执行暂离')
        self._map.open_retreat_dialog()
        self._map.confirm_leave()
